"""Red-team evaluation harness — entry point."""
import json
import logging

eval_logger = logging.getLogger("eval")
MAX_CONTEXT_LEN = 50_000


def _evaluate_prompt(prompt: str, category: str, model_id: str) -> dict:
    """Evaluate a single prompt, preserving category even on truncation."""
    result = {
        "model_id": model_id,
        "category": category,
        "prompt_length": len(prompt),
    }

    if len(prompt) > MAX_CONTEXT_LEN:
        result["output"] = "truncated"
        result["truncated"] = True
        eval_logger.warning(json.dumps({
            "event": "truncation",
            "model_id": model_id,
            "category": category,
            "prompt_length": len(prompt),
        }))
    else:
        result["output"] = "ok"
        result["truncated"] = False

    return result


def run_evaluation(model_id, config, prompt=None):
    category = config.get("category", "unknown")
    eval_logger.info(json.dumps({
        "event": "eval_start",
        "model_id": model_id,
        "config": config,
    }))

    if prompt is not None:
        result = _evaluate_prompt(prompt, category, model_id)
    else:
        score = 0.0
        result = {"model_id": model_id, "score": score, "category": category}

    eval_logger.info(json.dumps({
        "event": "eval_complete",
        "model_id": model_id,
        "category": category,
        "result": result,
    }))
    return result
